# Using Vicuna Language Model in SwiftUI

There are several approaches to integrate the Vicuna language model into a SwiftUI app. Here are the most practical methods:

---

## Option 1: Using llama.cpp via Swift (On-Device, Recommended)

Vicuna is based on LLaMA, so you can run it locally using [llama.cpp](https://github.com/ggerganov/llama.cpp) with its Swift bindings.

### Step 1: Add llama.cpp to Your Project

Add it as a Swift Package:

```
https://github.com/ggerganov/llama.cpp
```

Or use the community wrapper **[LLamaSwift](https://github.com/nicklama/llamaswift)** or **[llmfarm](https://github.com/nicklama/llamaswift)**.

### Step 2: Download a Vicuna GGUF Model

Download a quantized Vicuna model in GGUF format from [HuggingFace](https://huggingface.co/), e.g.:
- `vicuna-7b-v1.5.Q4_K_M.gguf`
- `vicuna-13b-v1.5.Q4_K_M.gguf`

Add it to your Xcode project bundle.

### Step 3: Create a Model Manager

```swift
import Foundation
import llama // or whichever binding you use

@MainActor
class VicunaModel: ObservableObject {
    @Published var response: String = ""
    @Published var isGenerating: Bool = false

    private var context: OpaquePointer?
    private var model: OpaquePointer?

    func loadModel() {
        llama_backend_init()

        guard let modelPath = Bundle.main.path(
            forResource: "vicuna-7b-v1.5.Q4_K_M",
            ofType: "gguf"
        ) else {
            print("Model file not found")
            return
        }

        var modelParams = llama_model_default_params()
        modelParams.n_gpu_layers = 0 // Set >0 if Metal GPU acceleration

        model = llama_load_model_from_file(modelPath, modelParams)

        var ctxParams = llama_context_default_params()
        ctxParams.n_ctx = 2048
        ctxParams.n_threads = 4

        context = llama_new_context_with_model(model, ctxParams)
    }

    func generate(prompt: String) async {
        isGenerating = true
        response = ""

        // Vicuna uses a specific prompt format
        let formattedPrompt = """
        A chat between a curious user and an artificial intelligence assistant. \
        The assistant gives helpful, detailed, and polite answers to the user's questions.

        USER: \(prompt)
        ASSISTANT:
        """

        // Tokenize and run inference
        await Task.detached(priority: .userInitiated) { [weak self] in
            guard let self = self else { return }
            // ... tokenization and generation logic using llama.cpp API
            // Update self.response on main thread as tokens are generated
        }.value

        isGenerating = false
    }

    deinit {
        if let context { llama_free(context) }
        if let model { llama_free_model(model) }
        llama_backend_free()
    }
}
```

### Step 4: Build the SwiftUI View

```swift
import SwiftUI

struct ChatView: View {
    @StateObject private var vicuna = VicunaModel()
    @State private var userInput: String = ""

    var body: some View {
        VStack(spacing: 16) {
            Text("Vicuna Chat")
                .font(.largeTitle)
                .bold()

            ScrollView {
                Text(vicuna.response)
                    .padding()
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
            .frame(maxHeight: .infinity)
            .background(Color(.systemGray6))
            .cornerRadius(12)

            HStack {
                TextField("Ask something...", text: $userInput)
                    .textFieldStyle(.roundedBorder)

                Button {
                    let prompt = userInput
                    userInput = ""
                    Task {
                        await vicuna.generate(prompt: prompt)
                    }
                } label: {
                    Image(systemName: "paperplane.fill")
                }
                .disabled(userInput.isEmpty || vicuna.isGenerating)
            }

            if vicuna.isGenerating {
                ProgressView("Generating...")
            }
        }
        .padding()
        .onAppear {
            vicuna.loadModel()
        }
    }
}
```

---

## Option 2: Using a Community Library (Easier Setup)

### Using [mlc-llm](https://github.com/mlc-ai/mlc-llm) (Supports iOS natively)

```swift
// MLC-LLM provides pre-built iOS packages for Vicuna
// Follow: https://mlc.ai/mlc-llm/docs/deploy/ios.html
```

### Using [LLMFarm](https://github.com/guinmoon/LLMFarm)

```swift
// Add via SPM
// https://github.com/guinmoon/llmfarm_core.swift

import llmfarm_core

class LLMManager: ObservableObject {
    @Published var output: String = ""
    private var ai: AI?

    func setup() {
        ai = AI(_modelPath: "path/to/vicuna.gguf", _chatName: "chat")
        ai?.initModel(.LLama, contextParams: .default)
    }

    func send(message: String) {
        let result = ai?.conversation(message) { str, _ in
            DispatchQueue.main.async {
                self.output += str
            }
            return false // return true to stop
        }
    }
}
```

---

## Option 3: API-Based Approach (Easiest)

If you're running Vicuna on a server (e.g., via [text-generation-webui](https://github.com/oobabooga/text-generation-webui) or [vLLM](https://github.com/vllm-project/vllm)):

```swift
import SwiftUI

class VicunaAPIClient: ObservableObject {
    @Published var response: String = ""

    private let baseURL = "http://localhost:8000/v1" // OpenAI-compatible API

    func sendMessage(_ message: String) async throws {
        let url = URL(string: "\(baseURL)/chat/completions")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body: [String: Any] = [
            "model": "vicuna-7b-v1.5",
            "messages": [
                ["role": "user", "content": message]
            ],
            "max_tokens": 512,
            "temperature": 0.7,
            "stream": false
        ]

        request.httpBody = try JSONSerialization.data(withJSONObject: body)

        let (data, _) = try await URLSession.shared.data(for: request)

        if let json = try JSONSerialization.jsonObject(with: data) as? [String: Any],
           let choices = json["choices"] as? [[String: Any]],
           let message = choices.first?["message"] as? [String: Any],
           let content = message["content"] as? String {
            await MainActor.run {
                self.response = content
            }
        }
    }
}

struct APIView: View {
    @StateObject private var client = VicunaAPIClient()
    @State private var input = ""

    var body: some View {
        VStack {
            ScrollView {
                Text(client.response)
                    .padding()
            }

            HStack {
                TextField("Message", text: $input)
                    .textFieldStyle(.roundedBorder)

                Button("Send") {
                    Task {
                        try? await client.sendMessage(input)
                        input = ""
                    }
                }
            }
            .padding()
        }
    }
}
```

---

## Comparison Table

| Approach | Difficulty | Offline | Performance | Model Size |
|----------|-----------|---------|-------------|------------|
| **llama.cpp** | Medium | ✅ | Good (Metal) | 4-8 GB |
| **LLMFarm** | Easy | ✅ | Good | 4-8 GB |
| **MLC-LLM** | Medium | ✅ | Best (optimized) | 4-8 GB |
| **API-based** | Easiest | ❌ | Depends on server | N/A |

---

## Important Notes

1. **Model Size**: Even quantized 7B models are ~4GB. Use `Q4_K_M` quantization for a good quality/size balance.
2. **Device Requirements**: On-device inference works best on iPhone 14 Pro+ / M1+ iPads/Macs with sufficient RAM.
3. **Metal Acceleration**: Enable GPU layers (`n_gpu_layers`) for significantly faster inference on Apple Silicon.
4. **Prompt Format**: Always use Vicuna's specific chat template (shown above) for best results.

